import{_ as d,C as c,o as a,c as h,a0 as o,b as r,w as i,a as l,E as n,a1 as s}from"./chunks/framework.CzVS_xMp.js";const g="data:image/svg+xml;base64,",I="data:image/svg+xml;base64,",p="/ai-data-center-systems/assets/liquid-cooling-methods-summary.DIm1BIVo.svg",m="data:image/svg+xml;base64,",u="/ai-data-center-systems/assets/nvidia-cooling-oversubscription-scenario.DVltO-an.png",f="/ai-data-center-systems/assets/nvidia-resolved-cooling-oversubscription.DM6ZNWco.png",P=JSON.parse('{"title":"Chapter 5: Thermal and Power Efficiency Considerations","description":"","frontmatter":{},"headers":[],"relativePath":"network/chap05/index.md","filePath":"network/chap05/index.md","lastUpdated":1788490169000}'),A={name:"network/chap05/index.md"};function C(b,e,w,y,k,G){const t=c("Mermaid");return a(),h("div",null,[e[8]||(e[8]=o('<h1 id="chapter-5-thermal-and-power-efficiency-considerations" tabindex="-1">Chapter 5: Thermal and Power Efficiency Considerations <a class="header-anchor" href="#chapter-5-thermal-and-power-efficiency-considerations" aria-label="Permalink to &quot;Chapter 5: Thermal and Power Efficiency Considerations&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#goal">Goal</a></li><li><a href="#thermal-footprints-in-ai-data-centers">Thermal Footprints in AI Data Centers</a><ul><li><a href="#why-ai-racks-consume-more-power">Why AI Racks Consume More Power</a></li><li><a href="#rack-power-budget">Rack Power Budget</a></li><li><a href="#power-usage-effectiveness-pue">Power Usage Effectiveness, PUE</a></li></ul></li><li><a href="#airflow-options">Airflow Options</a><ul><li><a href="#front-to-back-airflow">Front-to-Back Airflow</a></li><li><a href="#back-to-front-airflow">Back-to-Front Airflow</a></li><li><a href="#bidirectional-fans">Bidirectional Fans</a></li><li><a href="#choosing-fan-direction">Choosing Fan Direction</a></li></ul></li><li><a href="#liquid-cooling">Liquid Cooling</a><ul><li><a href="#why-liquid-cooling-is-becoming-necessary">Why Liquid Cooling Is Becoming Necessary</a></li><li><a href="#immersion-liquid-cooling">Immersion Liquid Cooling</a></li><li><a href="#single-phase-immersion-cooling">Single-Phase Immersion Cooling</a></li><li><a href="#two-phase-immersion-cooling">Two-Phase Immersion Cooling</a></li><li><a href="#cold-plate-liquid-cooling">Cold Plate Liquid Cooling</a></li><li><a href="#rear-door-heat-exchanger-liquid-cooling">Rear-Door Heat Exchanger Liquid Cooling</a></li><li><a href="#sprayed-liquid-cooling">Sprayed Liquid Cooling</a></li></ul></li><li><a href="#cooling-method-comparison">Cooling Method Comparison</a></li><li><a href="#rack-and-facility-design-implications">Rack and Facility Design Implications</a></li><li><a href="#operational-validation-checklist">Operational Validation Checklist</a></li><li><a href="#chapter-summary">Chapter Summary</a></li><li><a href="#key-terms">Key Terms</a></li><li><a href="#qa">Q&amp;A</a></li><li><a href="#references">References</a></li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>This chapter explains why AI/ML data centers create unusually high power and thermal requirements, and how rack airflow and liquid cooling approaches address those requirements.</p><p>The core idea is:</p><blockquote><p>AI data center design is constrained by power delivery and heat removal as much as by compute, network, or storage capacity.</p></blockquote><p>The chapter focuses on these topics:</p><ul><li>Thermal footprint of AI/ML racks</li><li>Power consumption of GPU servers, high-speed switches, and optics</li><li>Rack power budget and power density</li><li>Power Usage Effectiveness, PUE</li><li>Front-to-back, back-to-front, and bidirectional airflow</li><li>Liquid cooling as an alternative to air cooling</li><li>Immersion cooling, cold plate cooling, rear-door heat exchangers, and sprayed liquid cooling</li><li>Rack and facility design implications</li></ul>',9)),(a(),r(s,null,{default:i(()=>[n(t,{id:"mermaid-198",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20classDef%20compute%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20power%20fill%3A%235a3520%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20cooling%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20risk%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20facility%20fill%3A%235a3520%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20GPU%5BHigh-density%20GPU%20servers%5D%3A%3A%3Acompute%0A%20%20%20%20SW%5B400G%2F800G%20switches%20and%20optics%5D%3A%3A%3Acompute%0A%20%20%20%20PWR%5BRack%20power%20budget%3Cbr%2F%3EkW%20per%20rack%5D%3A%3A%3Apower%0A%20%20%20%20HEAT%5BHeat%20density%3Cbr%2F%3Ethermal%20footprint%5D%3A%3A%3Arisk%0A%20%20%20%20AIR%5BAirflow%20cooling%3Cbr%2F%3Efans%20and%20CRAH%2FCRAC%5D%3A%3A%3Acooling%0A%20%20%20%20LIQ%5BLiquid%20cooling%3Cbr%2F%3Eimmersion%2C%20cold%20plate%2C%20rear-door%2C%20spray%5D%3A%3A%3Acooling%0A%20%20%20%20PUE%5BPUE%20and%20sustainability%5D%3A%3A%3Afacility%0A%0A%20%20%20%20GPU%20--%3E%20PWR%0A%20%20%20%20SW%20--%3E%20PWR%0A%20%20%20%20PWR%20--%3E%20HEAT%0A%20%20%20%20HEAT%20--%3E%20AIR%0A%20%20%20%20HEAT%20--%3E%20LIQ%0A%20%20%20%20AIR%20--%3E%20PUE%0A%20%20%20%20LIQ%20--%3E%20PUE%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=o('<h2 id="thermal-footprints-in-ai-data-centers" tabindex="-1">Thermal Footprints in AI Data Centers <a class="header-anchor" href="#thermal-footprints-in-ai-data-centers" aria-label="Permalink to &quot;Thermal Footprints in AI Data Centers&quot;">​</a></h2><p>Data center power consumption is already a significant share of global power consumption, and AI/ML workloads increase this pressure. AI data centers use dense GPU servers, storage systems, high-speed switches, and optics. These devices do more work in less space, but they also consume more power and emit more heat per rack.</p><p>The physical design problem is direct:</p><ul><li>More GPUs per rack increase compute density.</li><li>More NICs per server increase network power draw.</li><li>400G/800G optics consume more power than older optics.</li><li>High-radix switches require large power supplies and fan capacity.</li><li>Heat removal must keep up with the compute and network plan.</li><li>Cooling systems themselves consume a large amount of facility power.</li></ul><h3 id="why-ai-racks-consume-more-power" tabindex="-1">Why AI Racks Consume More Power <a class="header-anchor" href="#why-ai-racks-consume-more-power" aria-label="Permalink to &quot;Why AI Racks Consume More Power&quot;">​</a></h3><p>AI/ML racks contain power-hungry equipment:</p><table tabindex="0"><thead><tr><th>Component</th><th>Power Driver</th></tr></thead><tbody><tr><td>Multi-GPU servers</td><td>GPUs, CPUs, memory, NICs, local storage, power supply redundancy</td></tr><tr><td>High-speed switches</td><td>ASIC power, fan power, control plane, high-radix port count</td></tr><tr><td>Optical modules</td><td>QSFP-DD, OSFP, 400G/800G transceivers</td></tr><tr><td>Storage systems</td><td>NVMe drives, storage controllers, storage NICs</td></tr><tr><td>Cooling equipment</td><td>Fans, pumps, chillers, heat exchangers</td></tr><tr><td>Power distribution</td><td>UPS, PDUs, conversion losses, lighting and facility overhead</td></tr></tbody></table><p>The chapter gives DGX H100-class systems as an example. A system can include six 3.3 kW power supplies with 4 + 2 redundancy. In that model, active consumption can be approximated as:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4 x 3.3 kW = 13.2 kW</span></span></code></pre></div><p>A single high-speed switch can also consume several kilowatts. Optics add more power: 400G/800G modules such as QSFP-DD and OSFP consume substantially more power than older 100G QSFP28 optics.</p><h3 id="rack-power-budget" tabindex="-1">Rack Power Budget <a class="header-anchor" href="#rack-power-budget" aria-label="Permalink to &quot;Rack Power Budget&quot;">​</a></h3><p>Traditional data center racks are often designed around roughly 10 kW to 25 kW per rack, with many facilities operating around 16 kW to 18 kW per rack. AI racks can exceed those assumptions quickly.</p><p>Example:</p><table tabindex="0"><thead><tr><th>Item</th><th>Approximate Impact</th></tr></thead><tbody><tr><td>One multi-GPU server</td><td>Can consume more than 10 kW</td></tr><tr><td>Two multi-GPU servers</td><td>May exceed a traditional rack power budget</td></tr><tr><td>One high-radix switch</td><td>Several kW, depending on model and optics</td></tr><tr><td>Dense 400G/800G optics</td><td>Adds front-panel heat and power draw</td></tr></tbody></table><p>This changes rack planning. AI clusters may require:</p><ul><li>Fewer servers per rack</li><li>Higher-capacity PDUs</li><li>More power feeds</li><li>Better phase balancing</li><li>Higher airflow</li><li>Liquid cooling</li><li>Wider aisles or specialized containment</li><li>Facility-level power upgrades</li></ul><h3 id="power-usage-effectiveness-pue" tabindex="-1">Power Usage Effectiveness, PUE <a class="header-anchor" href="#power-usage-effectiveness-pue" aria-label="Permalink to &quot;Power Usage Effectiveness, PUE&quot;">​</a></h3><p>Power Usage Effectiveness, PUE, measures data center energy efficiency.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUE = Total Facility Power / IT Equipment Power</span></span></code></pre></div><p><img src="'+g+'" alt="PUE formula and facility power components"></p><p>Where:</p><ul><li>Total Facility Power includes IT load plus cooling, power distribution, UPS losses, lighting, and facility overhead.</li><li>IT Equipment Power includes servers, storage, switches, and other computing equipment.</li></ul><p>An ideal PUE is <code>1.0</code>, meaning all power goes directly to IT equipment with no overhead. Real data centers are above <code>1.0</code>.</p><p>The chapter notes a typical data center power split:</p><table tabindex="0"><thead><tr><th>Category</th><th>Approximate Share</th></tr></thead><tbody><tr><td>IT equipment</td><td>40% to 45%</td></tr><tr><td>Cooling systems</td><td>35% to 40%</td></tr><tr><td>Power distribution, UPS, lighting, and other overhead</td><td>Remaining share</td></tr></tbody></table><p>Lowering PUE matters because cooling overhead can become nearly as important as the IT load itself.</p><h2 id="airflow-options" tabindex="-1">Airflow Options <a class="header-anchor" href="#airflow-options" aria-label="Permalink to &quot;Airflow Options&quot;">​</a></h2><p>The goal of airflow design is to remove heat with the least possible power. Fans are still the most common method for moving heat out of servers, storage devices, and switches.</p><p>Airflow direction must be coordinated across the rack. Servers, switches, storage systems, blanking panels, cable managers, and aisle containment should all support the same thermal design.</p><p><img src="'+I+'" alt="DGX H100/H200 airflow orientation"></p><p>For DGX H100/H200-class racks, design the row around front-to-rear server airflow. Use cold aisle supply and hot aisle exhaust, align switch airflow to the rack orientation, and avoid mixing airflow directions inside the same rack. At this density, aisle containment and full rack heat-load planning are usually more important than simply selecting larger fans.</p><p>Rear-mounted switches commonly use P2C airflow, while front-mounted switches may require C2P when hot aisle temperatures are too high for cabling.</p><h3 id="front-to-back-airflow" tabindex="-1">Front-to-Back Airflow <a class="header-anchor" href="#front-to-back-airflow" aria-label="Permalink to &quot;Front-to-Back Airflow&quot;">​</a></h3><p>In front-to-back airflow, cool air enters the front of the device and hot air exits the rear.</p><p>This is common in data centers and is usually preferred by customers.</p><p>Benefits:</p><ul><li>Aligns with hot-aisle/cold-aisle rack designs.</li><li>Cools switch optics first when ports are on the front panel.</li><li>Works well when servers, storage, and switches share the same direction.</li><li>Simplifies rack standardization.</li></ul><p>Trade-offs:</p><ul><li>Requires cable and airflow discipline at the front of the rack.</li><li>Dense front-panel optics may still require strong airflow and heat sinks.</li></ul>',39)),(a(),r(s,null,{default:i(()=>[n(t,{id:"mermaid-554",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20classDef%20cold%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20hot%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20eq%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20C%5BCold%20aisle%3Cbr%2F%3Efront%5D%3A%3A%3Acold%0A%20%20%20%20E%5BServer%20%2F%20switch%20%2F%20storage%5D%3A%3A%3Aeq%0A%20%20%20%20H%5BHot%20aisle%3Cbr%2F%3Erear%5D%3A%3A%3Ahot%0A%0A%20%20%20%20C%20--%3E%20E%20--%3E%20H%0A"})]),fallback:i(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=o('<h3 id="back-to-front-airflow" tabindex="-1">Back-to-Front Airflow <a class="header-anchor" href="#back-to-front-airflow" aria-label="Permalink to &quot;Back-to-Front Airflow&quot;">​</a></h3><p>In back-to-front airflow, cool air enters from the rear and hot air exits the front.</p><p>Benefits:</p><ul><li>Can cool power supply units first when their intake is at the rear.</li><li>May fit certain rack layouts or network rack designs.</li></ul><p>Trade-offs:</p><ul><li>Front-panel optics receive air later in the path.</li><li>Optics may need extra heat sinks.</li><li>The rack and all equipment must be aligned to this airflow model.</li><li>Mixed airflow directions can cause recirculation and hotspots.</li></ul>',6)),(a(),r(s,null,{default:i(()=>[n(t,{id:"mermaid-601",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20RL%0A%20%20%20%20classDef%20cold%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20hot%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20eq%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20C%5BCold%20air%3Cbr%2F%3Erear%5D%3A%3A%3Acold%0A%20%20%20%20E%5BServer%20%2F%20switch%20%2F%20storage%5D%3A%3A%3Aeq%0A%20%20%20%20H%5BHot%20air%3Cbr%2F%3Efront%5D%3A%3A%3Ahot%0A%0A%20%20%20%20C%20--%3E%20E%20--%3E%20H%0A"})]),fallback:i(()=>[...e[2]||(e[2]=[l(" Loading... ",-1)])]),_:1})),e[11]||(e[11]=o('<h3 id="bidirectional-fans" tabindex="-1">Bidirectional Fans <a class="header-anchor" href="#bidirectional-fans" aria-label="Permalink to &quot;Bidirectional Fans&quot;">​</a></h3><p>Bidirectional fans can support either airflow direction. Some designs can adjust fan direction based on heat sensors or deployment requirements.</p><p>Benefits:</p><ul><li>Flexible when airflow direction is uncertain during procurement.</li><li>Can adapt to different rack designs.</li><li>Reduces risk of ordering the wrong airflow direction.</li></ul><p>Trade-offs:</p><ul><li>More expensive.</li><li>More complex hardware design.</li><li>May not be cost-effective for large standardized deployments.</li><li>Still requires facility airflow planning.</li></ul><h3 id="choosing-fan-direction" tabindex="-1">Choosing Fan Direction <a class="header-anchor" href="#choosing-fan-direction" aria-label="Permalink to &quot;Choosing Fan Direction&quot;">​</a></h3><p>Once the rack and aisle design are defined, fan direction should normally be fixed before equipment is ordered.</p><p>For AI/ML clusters, the selected direction must account for:</p><ul><li>Server airflow direction</li><li>Switch airflow direction</li><li>Optics heat at the front panel</li><li>Storage airflow direction</li><li>Cable management</li><li>Hot aisle and cold aisle containment</li><li>Facility air-conditioning capacity</li><li>Maintenance access</li></ul><p>If airflow is inconsistent across devices, heat can recirculate inside the rack. This can increase fan speed, power consumption, link errors, thermal throttling, and hardware failure risk.</p><h2 id="liquid-cooling" tabindex="-1">Liquid Cooling <a class="header-anchor" href="#liquid-cooling" aria-label="Permalink to &quot;Liquid Cooling&quot;">​</a></h2><p>Air cooling becomes harder as rack power density rises. Liquid cooling is becoming more important because liquid can remove heat more efficiently than air.</p><h3 id="why-liquid-cooling-is-becoming-necessary" tabindex="-1">Why Liquid Cooling Is Becoming Necessary <a class="header-anchor" href="#why-liquid-cooling-is-becoming-necessary" aria-label="Permalink to &quot;Why Liquid Cooling Is Becoming Necessary&quot;">​</a></h3><p>Liquid cooling can:</p><ul><li>Remove more heat from high-density racks.</li><li>Reduce cooling power consumption.</li><li>Improve PUE.</li><li>Support higher processor and GPU performance.</li><li>Enable rack densities that are difficult with air cooling.</li><li>Reduce dependence on extremely high fan speeds.</li></ul><p>The chapter notes that liquid cooling can significantly reduce data center power consumption and improve PUE. It also cites market growth in data center liquid cooling as AI power density rises.</p><p>Liquid cooling is not a single design. The chapter discusses four main approaches:</p><ul><li>Immersion liquid cooling (침지식 액체 냉각)</li><li>Cold plate liquid cooling (콜드 플레이트 액체 냉각)</li><li>Rear-door heat exchanger liquid cooling (후면 도어 열교환기 액체 냉각)</li><li>Sprayed liquid cooling (분사식 액체 냉각)</li></ul><p><img src="'+p+'" alt="Summary of data center liquid cooling methods"></p><p>This simplified original diagram summarizes the same cooling categories discussed in the chapter. It is not a reproduction of the published figure from Wu et al.; the paper is listed in References only as a technical background source.</p><h3 id="immersion-liquid-cooling-침지식-액체-냉각" tabindex="-1">Immersion Liquid Cooling (침지식 액체 냉각) <a class="header-anchor" href="#immersion-liquid-cooling-침지식-액체-냉각" aria-label="Permalink to &quot;Immersion Liquid Cooling (침지식 액체 냉각)&quot;">​</a></h3><p>In immersion cooling, equipment is submerged in a dielectric coolant. The fluid absorbs heat from boards and components directly.</p><p>Requirements:</p><ul><li>Facility must be designed for immersion tanks.</li><li>Equipment must be qualified for immersion.</li><li>Maintenance processes must handle submerged hardware.</li><li>Coolant compatibility and lifecycle management must be planned.</li></ul><p>Benefits:</p><ul><li>Strong heat removal.</li><li>Supports very high power density.</li><li>Can improve power efficiency.</li><li>Reduces dependence on server fans.</li></ul><p>Limitations:</p><ul><li>Requires specialized facility design.</li><li>May complicate operations and maintenance.</li><li>Hardware must be immersion-compatible.</li><li>Less compatible with standard rack service workflows.</li></ul><h3 id="single-phase-immersion-cooling-단상-침지-냉각" tabindex="-1">Single-Phase Immersion Cooling (단상 침지 냉각) <a class="header-anchor" href="#single-phase-immersion-cooling-단상-침지-냉각" aria-label="Permalink to &quot;Single-Phase Immersion Cooling (단상 침지 냉각)&quot;">​</a></h3><p>In single-phase immersion cooling, the coolant remains liquid.</p><p>The cycle is:</p><ol><li>Equipment sits in a sealed tank of coolant.</li><li>Heat from components warms the coolant.</li><li>Pumps move warm coolant to a heat exchanger.</li><li>Water or another secondary loop removes heat from the coolant.</li><li>Cooled coolant returns to the tank.</li></ol>',33)),(a(),r(s,null,{default:i(()=>[n(t,{id:"mermaid-902",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20classDef%20tank%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20liquid%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20heat%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20R%5BRack%20submerged%20in%20coolant%5D%3A%3A%3Atank%0A%20%20%20%20HC%5BHot%20coolant%5D%3A%3A%3Aheat%0A%20%20%20%20HX%5BCoolant-to-water%3Cbr%2F%3Eheat%20exchanger%5D%3A%3A%3Aliquid%0A%20%20%20%20CW%5BCold%20water%20loop%5D%3A%3A%3Aliquid%0A%20%20%20%20CC%5BCold%20coolant%5D%3A%3A%3Aliquid%0A%0A%20%20%20%20R%20--%3E%20HC%20--%3E%20HX%0A%20%20%20%20CW%20--%3E%20HX%0A%20%20%20%20HX%20--%3E%20CC%20--%3E%20R%0A"})]),fallback:i(()=>[...e[3]||(e[3]=[l(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=o('<p>Single-phase immersion is conceptually simple, but it requires immersion-ready infrastructure and equipment.</p><h3 id="two-phase-immersion-cooling-2상-침지-냉각" tabindex="-1">Two-Phase Immersion Cooling (2상 침지 냉각) <a class="header-anchor" href="#two-phase-immersion-cooling-2상-침지-냉각" aria-label="Permalink to &quot;Two-Phase Immersion Cooling (2상 침지 냉각)&quot;">​</a></h3><p>In two-phase immersion cooling, the fluid has a boiling point below the temperature of hot components.</p><p>The cycle is:</p><ol><li>Components heat the liquid.</li><li>The liquid boils and becomes vapor.</li><li>Vapor rises toward a condenser or cold-water tube.</li><li>Vapor cools and condenses back into liquid droplets.</li><li>Droplets fall back into the liquid pool.</li></ol>',5)),(a(),r(s,null,{default:i(()=>[n(t,{id:"mermaid-942",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20classDef%20liquid%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20vapor%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20rack%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20C%5BCold%20condenser%20%2F%20water%20tube%5D%3A%3A%3Aliquid%0A%20%20%20%20V%5BVapor%20rises%5D%3A%3A%3Avapor%0A%20%20%20%20D%5BCondensed%20droplets%20fall%5D%3A%3A%3Aliquid%0A%20%20%20%20R%5BSubmerged%20equipment%5D%3A%3A%3Arack%0A%20%20%20%20L%5BLiquid%20coolant%20pool%5D%3A%3A%3Aliquid%0A%0A%20%20%20%20R%20--%3E%20L%20--%3E%20V%20--%3E%20C%20--%3E%20D%20--%3E%20L%0A"})]),fallback:i(()=>[...e[4]||(e[4]=[l(" Loading... ",-1)])]),_:1})),e[13]||(e[13]=o('<p>Two-phase immersion can avoid a separate external heat exchanger inside the coolant loop because phase change happens inside the tank. It is efficient, but it requires carefully selected fluids and specialized operational procedures.</p><h3 id="cold-plate-liquid-cooling-콜드-플레이트-냉각" tabindex="-1">Cold Plate Liquid Cooling (콜드 플레이트 냉각) <a class="header-anchor" href="#cold-plate-liquid-cooling-콜드-플레이트-냉각" aria-label="Permalink to &quot;Cold Plate Liquid Cooling (콜드 플레이트 냉각)&quot;">​</a></h3><p>Cold plate cooling is also called direct-to-chip liquid cooling (직접 칩 냉각).</p><p>In this design:</p><ul><li>Cold plates or heat sinks attach directly to CPUs, GPUs, memory, or other hot components.</li><li>Cool liquid flows through tubes to the plates.</li><li>Heat transfers from the component to the liquid.</li><li>Warm liquid moves to a heat exchanger.</li><li>Cooled liquid returns to the cold plates.</li></ul>',5)),(a(),r(s,null,{default:i(()=>[n(t,{id:"mermaid-982",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20classDef%20component%20fill%3A%235a3520%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20liquid%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20heat%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20P%5BPump%5D%3A%3A%3Aliquid%0A%20%20%20%20C%5BCold%20liquid%5D%3A%3A%3Aliquid%0A%20%20%20%20CP%5BCold%20plate%20on%20CPU%2FGPU%5D%3A%3A%3Acomponent%0A%20%20%20%20W%5BWarm%20liquid%5D%3A%3A%3Aheat%0A%20%20%20%20HX%5BHeat%20exchanger%5D%3A%3A%3Aliquid%0A%0A%20%20%20%20P%20--%3E%20C%20--%3E%20CP%20--%3E%20W%20--%3E%20HX%20--%3E%20P%0A"})]),fallback:i(()=>[...e[5]||(e[5]=[l(" Loading... ",-1)])]),_:1})),e[14]||(e[14]=o('<p>Benefits:</p><ul><li>Targeted heat removal from the hottest components.</li><li>Equipment does not need to be fully submerged.</li><li>Can be cheaper and more flexible than immersion.</li><li>Can coexist with air cooling for other components.</li></ul><p>Limitations:</p><ul><li>Requires plumbing inside the rack or chassis.</li><li>Requires leak detection and service procedures.</li><li>Not all components are cooled directly.</li><li>Still requires facility water or heat exchange infrastructure.</li></ul><h3 id="rear-door-heat-exchanger-liquid-cooling-후면-도어-열교환기-액체-냉각" tabindex="-1">Rear-Door Heat Exchanger Liquid Cooling (후면 도어 열교환기 액체 냉각) <a class="header-anchor" href="#rear-door-heat-exchanger-liquid-cooling-후면-도어-열교환기-액체-냉각" aria-label="Permalink to &quot;Rear-Door Heat Exchanger Liquid Cooling (후면 도어 열교환기 액체 냉각)&quot;">​</a></h3><p>Rear-door heat exchanger cooling uses a radiator-like door at the back of the rack. Hot exhaust air from the equipment passes through the rear-door heat exchanger. A chilled-water loop absorbs heat from the air.</p><p>Benefits:</p><ul><li>Can support high-density racks, such as around 20 kW at standard chilled-water design temperatures.</li><li>Does not require changing servers or switches.</li><li>Works with air-cooled equipment.</li><li>Can be simpler than immersion or direct-to-chip retrofits.</li></ul><p>Limitations:</p><ul><li>Less efficient than immersion and cold plate liquid cooling.</li><li>Requires data center design support.</li><li>Works best with front-to-back airflow.</li><li>Adds rear-rack weight, plumbing, and service considerations.</li></ul>',10)),(a(),r(s,null,{default:i(()=>[n(t,{id:"mermaid-1089",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20classDef%20cold%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20hot%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20water%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20C%5BCold%20aisle%5D%3A%3A%3Acold%0A%20%20%20%20R%5BRack%20equipment%5D%3A%3A%3Ahot%0A%20%20%20%20D%5BRear-door%20heat%20exchanger%5D%3A%3A%3Awater%0A%20%20%20%20A%5BCooler%20exhaust%20air%5D%3A%3A%3Acold%0A%20%20%20%20W%5BWarm%20water%20to%20cooling%20plant%5D%3A%3A%3Awater%0A%0A%20%20%20%20C%20--%3E%20R%20--%3E%20D%20--%3E%20A%0A%20%20%20%20D%20--%3E%20W%0A"})]),fallback:i(()=>[...e[6]||(e[6]=[l(" Loading... ",-1)])]),_:1})),e[15]||(e[15]=o('<p>The chapter also refers to this approach as air-assisted liquid cooling. The equipment remains air cooled, but liquid removes heat at the rack rear.</p><h3 id="sprayed-liquid-cooling-분사식-액체-냉각" tabindex="-1">Sprayed Liquid Cooling (분사식 액체 냉각) <a class="header-anchor" href="#sprayed-liquid-cooling-분사식-액체-냉각" aria-label="Permalink to &quot;Sprayed Liquid Cooling (분사식 액체 냉각)&quot;">​</a></h3><p>Sprayed liquid cooling sprays coolant through nozzles onto heat-generating components.</p><p>Benefits:</p><ul><li>Targeted cooling.</li><li>Uses less coolant than some other liquid cooling methods.</li><li>Can reduce energy consumption compared with air-cooled designs.</li><li>Similar in spirit to cold plate cooling, but coolant is sprayed instead of circulated through a plate.</li></ul><p>Limitations:</p><ul><li>Equipment must be modified to support spray devices.</li><li>Requires liquid management inside the chassis or enclosure.</li><li>Requires careful maintenance and reliability planning.</li></ul><p>The chapter notes that sprayed liquid cooling can reduce total data center energy consumption compared with air cooling.</p><h2 id="cooling-method-comparison" tabindex="-1">Cooling Method Comparison <a class="header-anchor" href="#cooling-method-comparison" aria-label="Permalink to &quot;Cooling Method Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cooling Method</th><th>Main Idea</th><th>Strength</th><th>Limitation</th></tr></thead><tbody><tr><td>Front-to-back airflow</td><td>Air enters front, exits rear</td><td>Standard data center pattern, good for front-panel optics</td><td>Limited at very high power density</td></tr><tr><td>Back-to-front airflow</td><td>Air enters rear, exits front</td><td>Can cool power supplies first</td><td>Optics get warmer air later</td></tr><tr><td>Bidirectional fans</td><td>Configurable airflow direction</td><td>Procurement and deployment flexibility</td><td>Higher cost and complexity</td></tr><tr><td>Single-phase immersion</td><td>Equipment submerged in liquid coolant</td><td>Strong heat removal, high density</td><td>Specialized tanks, compatible hardware required</td></tr><tr><td>Two-phase immersion</td><td>Coolant boils and condenses inside tank</td><td>Efficient phase-change cooling</td><td>Specialized fluids and procedures</td></tr><tr><td>Cold plate</td><td>Liquid runs to plates on hot chips</td><td>Targeted direct-to-chip cooling</td><td>Plumbing, leak detection, component coverage</td></tr><tr><td>Rear-door heat exchanger</td><td>Liquid-cooled rear rack door absorbs exhaust heat</td><td>Works with normal air-cooled gear</td><td>Less efficient than direct liquid methods</td></tr><tr><td>Sprayed liquid cooling</td><td>Coolant sprayed onto hot surfaces</td><td>Targeted and coolant-efficient</td><td>Requires modified equipment</td></tr></tbody></table><h2 id="rack-and-facility-design-implications" tabindex="-1">Rack and Facility Design Implications <a class="header-anchor" href="#rack-and-facility-design-implications" aria-label="Permalink to &quot;Rack and Facility Design Implications&quot;">​</a></h2><p>Thermal and power planning must be integrated with network design. For AI fabrics, the rack is not just a physical container; it is a power, cooling, cabling, and service domain.</p><p><img src="'+m+'" alt="Cooling oversubscription and rack spacing"></p><p>Cooling oversubscription is a facility-level problem, not just a rack airflow problem. Even when airflow direction is correct, a dense row can produce more heat than the local cooling footprint can remove. In that case, mitigation may require reducing rack density, spacing populated racks apart, or changing the row layout. This improves cooling headroom, but it consumes more floor space and can increase cable length.</p><p><img src="'+u+'" alt="NVIDIA cooling oversubscription scenario"></p><p><img src="'+f+'" alt="NVIDIA resolved cooling oversubscription scenario"></p><p>Source: NVIDIA, <a href="https://docs.nvidia.com/dgx-superpod/design-guides/dgx-superpod-data-center-design-h100/latest/cooling.html" target="_blank" rel="noreferrer">DGX SuperPOD Data Center Design Featuring DGX H100 Systems, Cooling and Airflow Optimization</a>, Figure 21 and Figure 22.</p><p>Important design implications:</p><ul><li>Rack power density determines how many GPU servers can fit safely.</li><li>Cooling design may limit server count before rack units are physically full.</li><li>Switch and optics heat must be included in thermal planning.</li><li>Airflow direction must match across servers, switches, and storage.</li><li>Cable bundles must not block airflow.</li><li>High-power racks may need wider aisles or containment changes.</li><li>Liquid-cooled racks require plumbing, leak detection, maintenance clearance, and facility water loops.</li><li>PDU and UPS capacity must be sized for peak and redundant loads.</li><li>Power feed redundancy must match workload availability targets.</li><li>Thermal telemetry should be collected with network and server telemetry.</li></ul><h2 id="operational-validation-checklist" tabindex="-1">Operational Validation Checklist <a class="header-anchor" href="#operational-validation-checklist" aria-label="Permalink to &quot;Operational Validation Checklist&quot;">​</a></h2><p>Use this checklist before finalizing an AI data center rack and cooling design.</p>',21)),(a(),r(s,null,{default:i(()=>[n(t,{id:"mermaid-1364",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20classDef%20step%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20test%20fill%3A%23173f32%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20risk%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20done%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%0A%20%20%20%20A%5BInventory%20server%2C%20switch%2C%20optics%20power%5D%3A%3A%3Astep%0A%20%20%20%20B%5BCalculate%20rack%20kW%20and%20redundancy%5D%3A%3A%3Astep%0A%20%20%20%20C%5BChoose%20airflow%20or%20liquid%20cooling%20model%5D%3A%3A%3Astep%0A%20%20%20%20D%5BValidate%20PDU%2C%20UPS%2C%20and%20facility%20capacity%5D%3A%3A%3Atest%0A%20%20%20%20E%5BModel%20heat%20removal%20and%20airflow%20path%5D%3A%3A%3Atest%0A%20%20%20%20F%5BTest%20thermal%20telemetry%20under%20load%5D%3A%3A%3Atest%0A%20%20%20%20G%7BTemperature%20and%20PUE%20targets%20met%3F%7D%3A%3A%3Arisk%0A%20%20%20%20H%5BApprove%20rack%20design%5D%3A%3A%3Adone%0A%20%20%20%20I%5BRevise%20density%2C%20cooling%2C%20or%20power%20design%5D%3A%3A%3Arisk%0A%0A%20%20%20%20A%20--%3E%20B%20--%3E%20C%20--%3E%20D%20--%3E%20E%20--%3E%20F%20--%3E%20G%0A%20%20%20%20G%20--%3E%7CYes%7C%20H%0A%20%20%20%20G%20--%3E%7CNo%7C%20I%20--%3E%20B%0A"})]),fallback:i(()=>[...e[7]||(e[7]=[l(" Loading... ",-1)])]),_:1})),e[16]||(e[16]=o('<p>Checklist:</p><ul><li>Calculate server, switch, optics, storage, and management power per rack.</li><li>Include redundant power supply behavior, not only nameplate power.</li><li>Verify PDU, branch circuit, UPS, and generator capacity.</li><li>Confirm airflow direction before ordering equipment.</li><li>Avoid mixing airflow directions in the same rack.</li><li>Validate hot-aisle/cold-aisle containment.</li><li>Confirm cable routing does not block fan intake or exhaust.</li><li>Monitor inlet temperature, outlet temperature, fan speed, and thermal throttling.</li><li>Monitor optics temperature and link error counters.</li><li>Confirm cooling capacity at peak training workload.</li><li>Measure PUE impact of the proposed design.</li><li>For liquid cooling, validate facility water availability and quality.</li><li>For cold plate, validate quick-disconnects, leak detection, and service workflow.</li><li>For immersion, validate tank maintenance, coolant compatibility, and hardware qualification.</li><li>For rear-door heat exchangers, validate door weight, clearance, and chilled-water loop.</li><li>For sprayed liquid cooling, validate equipment modifications and spray reliability.</li><li>Ensure operations staff can service failed servers, switches, optics, and pumps.</li><li>Keep thermal design documents aligned with rack elevation and cable plans.</li></ul><h2 id="chapter-summary" tabindex="-1">Chapter Summary <a class="header-anchor" href="#chapter-summary" aria-label="Permalink to &quot;Chapter Summary&quot;">​</a></h2><p>AI/ML data centers have much higher power and cooling requirements than traditional data centers because GPU servers, high-speed switches, and optics concentrate more power into each rack.</p><p>Traditional racks often operate around 10 kW to 25 kW, while modern AI racks can exceed those assumptions quickly. A single DGX H100-class system can consume more than 10 kW, and switches plus optics add additional heat.</p><p>PUE measures data center efficiency as total facility power divided by IT equipment power. Because cooling systems can consume a large share of total facility power, thermal design has a direct effect on operating cost and sustainability.</p><p>Air cooling remains common, but airflow direction must be chosen carefully. Front-to-back airflow is commonly preferred and helps cool front-panel optics first. Back-to-front airflow cools power supplies first but may leave optics hotter. Bidirectional fans provide flexibility at higher cost.</p><p>Liquid cooling is becoming more important for high-density AI racks. Immersion cooling submerges equipment in coolant, cold plate cooling targets CPUs and GPUs directly, rear-door heat exchangers remove heat from rack exhaust air, and sprayed liquid cooling sprays coolant onto hot components.</p><p>No cooling method is universally best. The right choice depends on rack power density, facility design, equipment compatibility, maintenance model, cost, and sustainability goals.</p><h2 id="key-terms" tabindex="-1">Key Terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key Terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>PUE</td><td>Power Usage Effectiveness, total facility power divided by IT equipment power</td></tr><tr><td>IT Equipment Power</td><td>Power consumed by servers, storage, switches, and IT gear</td></tr><tr><td>Total Facility Power</td><td>IT load plus cooling, power distribution, UPS losses, lighting, and overhead</td></tr><tr><td>Thermal Footprint</td><td>Heat output and cooling impact of equipment or a rack</td></tr><tr><td>Front-to-Back Airflow</td><td>Air enters the equipment front and exits the rear</td></tr><tr><td>Back-to-Front Airflow</td><td>Air enters the equipment rear and exits the front</td></tr><tr><td>Bidirectional Fan</td><td>Fan system that can support either airflow direction</td></tr><tr><td>Immersion Cooling</td><td>Cooling method where equipment is submerged in dielectric liquid</td></tr><tr><td>Single-Phase Immersion</td><td>Immersion cooling where coolant remains liquid</td></tr><tr><td>Two-Phase Immersion</td><td>Immersion cooling where coolant boils and condenses</td></tr><tr><td>Cold Plate Cooling</td><td>Direct-to-chip liquid cooling using plates attached to hot components</td></tr><tr><td>Rear-Door Heat Exchanger</td><td>Liquid-cooled door that absorbs heat from rack exhaust air</td></tr><tr><td>Sprayed Liquid Cooling</td><td>Cooling method where coolant is sprayed onto hot surfaces</td></tr><tr><td>Heat Exchanger</td><td>Device that transfers heat from one fluid loop to another</td></tr><tr><td>Chilled Water Loop</td><td>Facility cooling loop carrying cold water to remove heat</td></tr><tr><td>Rack Power Density</td><td>Power consumed per rack, usually measured in kW</td></tr><tr><td>Thermal Throttling</td><td>Performance reduction caused by overheating</td></tr><tr><td>UPS</td><td>Uninterruptible Power Supply</td></tr><tr><td>PDU</td><td>Power Distribution Unit</td></tr></tbody></table><h2 id="q-a" tabindex="-1">Q&amp;A <a class="header-anchor" href="#q-a" aria-label="Permalink to &quot;Q&amp;A&quot;">​</a></h2><h3 id="_1-why-do-ai-ml-data-centers-have-higher-power-and-cooling-requirements-than-traditional-data-centers" tabindex="-1">1. Why do AI/ML data centers have higher power and cooling requirements than traditional data centers? <a class="header-anchor" href="#_1-why-do-ai-ml-data-centers-have-higher-power-and-cooling-requirements-than-traditional-data-centers" aria-label="Permalink to &quot;1. Why do AI/ML data centers have higher power and cooling requirements than traditional data centers?&quot;">​</a></h3><p>At a high level, AI/ML data centers concentrate far more compute, network, and storage capacity into each rack than traditional enterprise data centers. A single multi-GPU server can consume more than 10 kW, and the rack may also contain high-radix switches, 400G/800G optics, storage devices, PDUs, and management equipment. All of that power becomes heat that must be removed reliably.</p><p>The key point is that the problem is not just total facility power. It is power density. Traditional racks might have been designed around 10 kW to 25 kW, while AI racks can exceed those assumptions quickly. Once power density rises, airflow, cable routing, service clearance, and cooling capacity all become design constraints.</p><p>The practical answer is: AI data centers need more power and cooling because they are built to keep expensive accelerators busy. If the facility cannot deliver power or remove heat, the GPUs may throttle, fail, or sit idle.</p><h3 id="_2-what-is-pue-and-how-is-it-calculated" tabindex="-1">2. What is PUE, and how is it calculated? <a class="header-anchor" href="#_2-what-is-pue-and-how-is-it-calculated" aria-label="Permalink to &quot;2. What is PUE, and how is it calculated?&quot;">​</a></h3><p>PUE, Power Usage Effectiveness, measures how efficiently a data center uses power. The formula is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUE = Total Facility Power / IT Equipment Power</span></span></code></pre></div><p>IT equipment power is the load consumed by servers, storage, switches, GPUs, NICs, and similar equipment. Total facility power includes the IT load plus cooling, UPS losses, power distribution losses, lighting, pumps, fans, and other overhead.</p><p>The intuition is simple: if a site has a PUE of <code>1.3</code>, then for every 1 MW used by IT equipment, the facility uses about 0.3 MW of additional overhead. The ideal PUE is <code>1.0</code>, but real facilities are above that. For AI data centers, PUE matters because cooling overhead can become a large part of the operating cost.</p><h3 id="_3-how-do-front-to-back-back-to-front-and-bidirectional-airflow-differ" tabindex="-1">3. How do front-to-back, back-to-front, and bidirectional airflow differ? <a class="header-anchor" href="#_3-how-do-front-to-back-back-to-front-and-bidirectional-airflow-differ" aria-label="Permalink to &quot;3. How do front-to-back, back-to-front, and bidirectional airflow differ?&quot;">​</a></h3><p>Front-to-back airflow takes in cold air at the equipment front and exhausts hot air out the rear. This aligns well with cold aisle and hot aisle data center layouts, and it is the expected orientation for DGX H100/H200-class servers.</p><p>Back-to-front airflow does the reverse. It can be useful for some network devices depending on where the switch is mounted and where the connector side faces. For example, rear-mounted network switches may use P2C airflow so the switch still follows the rack-level cold-to-hot direction.</p><p>Bidirectional fans add flexibility because the same platform can support either direction, but they increase cost and complexity. Airflow direction should not be treated as an afterthought. Mixed airflow in the same rack can create recirculation, raise inlet temperatures, and reduce cooling efficiency.</p><h3 id="_4-how-does-immersion-cooling-work" tabindex="-1">4. How does immersion cooling work? <a class="header-anchor" href="#_4-how-does-immersion-cooling-work" aria-label="Permalink to &quot;4. How does immersion cooling work?&quot;">​</a></h3><p>Immersion cooling places equipment directly in a dielectric coolant. The coolant absorbs heat from the electronics and transfers it to a heat exchanger or condenser. In single-phase immersion, the coolant stays liquid. In two-phase, or 2상, immersion, the coolant boils into vapor and then condenses back into liquid.</p><p>The main advantage is heat removal. Immersion cooling can support very high power density and can reduce reliance on high-speed fans. It can also improve facility efficiency when the full cooling loop is designed well.</p><p>The trade-off is operational change. The servers, boards, connectors, materials, maintenance process, and facility layout all need to be compatible with immersion. Immersion is powerful, but it is not a simple drop-in replacement for air cooling.</p><h3 id="_5-what-is-cold-plate-cooling" tabindex="-1">5. What is cold plate cooling? <a class="header-anchor" href="#_5-what-is-cold-plate-cooling" aria-label="Permalink to &quot;5. What is cold plate cooling?&quot;">​</a></h3><p>Cold plate cooling, often called direct-to-chip liquid cooling, attaches liquid-cooled plates to hot components such as CPUs, GPUs, or memory devices. Cool liquid flows through the plate, absorbs heat from the component, and then carries that heat to a heat exchanger or facility water loop.</p><p>The reason this is attractive is that it targets the highest heat sources without submerging the entire server. That makes it more compatible with conventional rack operations than immersion cooling. Some components can still be air cooled while the CPUs and GPUs use liquid.</p><p>The engineering trade-off is plumbing. You need manifolds, hoses, quick disconnects, leak detection, service procedures, and facility water planning. Cold plate cooling is efficient, but it moves part of the reliability problem from airflow into liquid distribution and maintenance.</p><h3 id="_6-what-are-the-trade-offs-between-air-and-liquid-cooling" tabindex="-1">6. What are the trade-offs between air and liquid cooling? <a class="header-anchor" href="#_6-what-are-the-trade-offs-between-air-and-liquid-cooling" aria-label="Permalink to &quot;6. What are the trade-offs between air and liquid cooling?&quot;">​</a></h3><p>Air cooling is simpler, familiar, and usually cheaper to operate from a hardware-service perspective. It works well when rack power density is moderate and airflow is well managed with cold aisle supply, hot aisle exhaust, blanking panels, and containment.</p><p>The limitation is heat capacity. At high AI rack densities, air can require large fan power, high airflow volume, and careful facility design. Eventually, the rack may be physically full of cooling constraints before it is full of servers.</p><p>Liquid cooling removes heat more efficiently and can improve PUE, but it introduces specialized infrastructure. The site needs liquid loops, pumps, heat exchangers, leak management, trained operators, and hardware qualified for the cooling method. Liquid cooling solves one scaling problem, but it introduces a new operational model.</p><h3 id="_7-how-does-rack-design-influence-cooling-strategy" tabindex="-1">7. How does rack design influence cooling strategy? <a class="header-anchor" href="#_7-how-does-rack-design-influence-cooling-strategy" aria-label="Permalink to &quot;7. How does rack design influence cooling strategy?&quot;">​</a></h3><p>Rack design directly determines whether the cooling plan is practical. Rack height, width, depth, side panels, cable ingress, blanking panels, door choice, PDU placement, and sensor placement all affect airflow and serviceability.</p><p>For DGX H100/H200-class racks, the starting point is front-to-rear server airflow and a row design based on cold aisle supply and hot aisle exhaust. Switch airflow must be aligned with the rack orientation. If a rear-mounted switch faces the hot aisle, P2C airflow may be appropriate. If hot aisle temperatures are too high for cabling, the switch placement and airflow may need to change.</p><p>The other constraint is cooling capacity per footprint. Even if airflow direction is correct, a dense row can exceed the local cooling capacity. That is why rack spacing, rack density, containment, cable length, and facility cooling capacity must be considered together.</p><h3 id="_8-why-does-cooling-efficiency-affect-sustainability" tabindex="-1">8. Why does cooling efficiency affect sustainability? <a class="header-anchor" href="#_8-why-does-cooling-efficiency-affect-sustainability" aria-label="Permalink to &quot;8. Why does cooling efficiency affect sustainability?&quot;">​</a></h3><p>Cooling efficiency matters because cooling is not a small overhead. In many data centers, cooling systems consume a large share of facility power. If the cooling design is inefficient, the site burns more energy just to remove heat from the IT load.</p><p>From a sustainability point of view, better cooling reduces total energy consumption, operating cost, and carbon impact. It can also allow more compute capacity within the same power envelope. That is especially important for AI data centers because demand for GPU capacity is growing faster than many facilities can add power.</p><p>In practice, sustainability comes back to engineering discipline. Good airflow management, accurate thermal telemetry, correct rack density, efficient liquid cooling where needed, and realistic PUE targets all help the data center deliver more useful compute per watt.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://www.datacenterknowledge.com/management/power-shortages-will-restrict-40-of-ai-data-centers-by-2027-gartner" target="_blank" rel="noreferrer">Data Center Knowledge, &quot;Power Shortages Will Restrict 40% of AI Data Centers by 2027, Gartner&quot;</a></li><li><a href="https://www.iea.org/reports/energy-and-ai" target="_blank" rel="noreferrer">IEA, Energy and AI</a></li><li><a href="https://www.ashrae.org/" target="_blank" rel="noreferrer">ASHRAE, American Society of Heating, Refrigerating and Air-Conditioning Engineers</a></li><li><a href="https://ashrae.org.vn/wp-content/uploads/2024/12/Topic-1-AIDC-Infrastructure-revolution-and-liquid-cooling-application.pdf" target="_blank" rel="noreferrer">ASHRAE, AIDC Infrastructure Revolution and Liquid Cooling Application</a></li><li><a href="https://doi.org/10.1016/j.ces.2025.121525" target="_blank" rel="noreferrer">Wu et al., &quot;A comprehensive review of cold plate liquid cooling technology for data centers,&quot; Chemical Engineering Science, 2025</a></li><li><a href="https://docs.nvidia.com/dgx-superpod/design-guides/dgx-superpod-data-center-design-h100/latest/cooling.html" target="_blank" rel="noreferrer">NVIDIA, DGX SuperPOD Data Center Design Featuring DGX H100 Systems, Cooling and Airflow Optimization</a></li><li><a href="https://docs.nvidia.com/dgx-superpod/design-guides/dgx-superpod-data-center-design-h100/latest/infrastructure.html" target="_blank" rel="noreferrer">NVIDIA, DGX SuperPOD Data Center Design Featuring DGX H100 Systems, White Space Infrastructure</a></li><li><a href="https://www.naddod.com/blog/data-center-liquid-cooling-technology-and-trends-analysis" target="_blank" rel="noreferrer">Naddod, &quot;Data Center Liquid Cooling Technology and Trends Analysis (2025)&quot;</a></li></ul>',47))])}const D=d(A,[["render",C]]);export{P as __pageData,D as default};
